using CS2Review.Core;
using System.Text.Json;

static class RatingRuleTests
{
    public static RatingModel Model(bool negative=false) => RatingModelCodec.Seal(new() {TrainingManifestSha256=new string('c',64),ProbabilityPriorWeight=0,MinimumMapObservations=1000,Weights=[1d/6,1d/6,1d/6,1d/6,1d/6,1d/6],ProbabilityCells=[Cell(2,2,false,50),Cell(1,2,false,negative?80:20),Cell(2,2,true,30),Cell(1,2,true,10)] });
    static RatingProbabilityCell Cell(int ct,int t,bool planted,int ctWins) => new(){Map="global",CtAlive=ct,TAlive=t,CtEquipmentBand=2,TEquipmentBand=2,Planted=planted,ClockBand=planted?3:0,Observations=100,CtWins=ctWins};
    public static RoundData Round(int n=1) => new(){Number=n,IsValid=true,Winner="T",StartedAt=0,EndedAt=100,FreezeEndedAt=0,BombTimerSeconds=40,Participants=[new(){PlayerId="p",Side="T"},new(){PlayerId="mate",Side="T"},new(){PlayerId="e",Side="CT"},new(){PlayerId="e2",Side="CT"}],EconomySnapshots=[State("p","T",0,0),State("mate","T",0,0),State("e","CT",0,0),State("e2","CT",0,0)],Survivors=["p","mate","e2"]};
    public static PlayerState State(string id,string side,int tick,double time,int health=100,int equipment=3000,bool? kit=false) => new(){PlayerId=id,Side=side,Tick=tick,Time=time,Health=health,EquipmentValue=equipment,DefuseKit=kit};
    public static GameEvent Kill(string id,double time,string actor="p",string target="e") => new(){Id=id,Kind="kill",Tick=(int)(time*100),Time=time,ActorId=actor,TargetId=target,ActorState=State(actor,actor is "p" or "mate"?"T":"CT",(int)(time*100),time),TargetState=State(target,target is "p" or "mate"?"T":"CT",(int)(time*100),time,0)};
    public static GameEvent Damage(string id,double time,string actor,int amount) => new(){Id=id,Kind="damage",Tick=(int)(time*100),Time=time,ActorId=actor,TargetId="e",Damage=amount,ActorState=State(actor,"T",(int)(time*100),time),TargetState=State("e","CT",(int)(time*100),time,100-amount)};
    public static GameEvent Bomb(string kind,string id,double time,string actor="p") => new(){Id=id,Kind=kind,Tick=(int)(time*100),Time=time,ActorId=actor,ActorState=State(actor,actor is "p" or "mate"?"T":"CT",(int)(time*100),time)};
    public static MatchData Match(params RoundData[] rounds) => new(){Id="m",MapName="de_mirage",SourceSha256=new string('a',64),Players=[new(){Id="p",Name="P"},new(){Id="mate",Name="Mate"},new(){Id="e",Name="Enemy"},new(){Id="e2",Name="Enemy2"}],Rounds=rounds.ToList()};
    public static RatingResult Score(RoundData r,string p="p",RatingModel? model=null) => new RatingEngine().Score(Match(r),p,model??Model());
    public static RatingEventCredit Credit(RatingResult r,string id) => r.Credits.Single(c=>c.EventId==id);
    public static void Near(double e,double? a,double tolerance=1e-9){if(a is not double v||Math.Abs(e-v)>tolerance)throw new Exception($"expected {e}, got {a}");}
    public static void Yes(bool v,string message){if(!v)throw new Exception(message);}

    public static void Run()
    {
        var failures=new List<string>();var count=0;
        void Test(string name,Action body){count++;try{body();Console.WriteLine("PASS "+name);}catch(Exception ex){failures.Add(name);Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        Test("known kill delta and residual",()=>{var r=Round();r.Events=[Kill("k",20)];var a=Score(r);Near(.3,Credit(a,"k").PlayerCredits["p"]);Near(-.3,Credit(a,"k").PlayerCredits["e"]);Near(.2,Credit(a,"round-1-residual").PlayerCredits["p"]);Near(50,a.RoundSwing);Yes(a.Overall is not null,"unavailable complete experiment");});
        Test("negative killer correction preserves victim debit",()=>{var r=Round();r.Events=[Kill("k",20)];var c=Credit(Score(r,model:Model(true)),"k");Near(0,c.PlayerCredits.GetValueOrDefault("p"));Near(-.3,c.PlayerCredits["e"]);Yes(c.NegativeKillerCorrection,"unmarked correction");});
        Test("forty damage assist uses scoring KAST",()=>{foreach(var amount in new[]{39,40}){var r=Round();r.Survivors=["p","e2"];r.Events=[Damage("hit",10,"mate",amount),Kill("k",20)];var a=Score(r,"mate");Near(amount==40?100:0,a.ScoringKastPercent);Near(0,a.Raw.Assists);}});
        Test("damage credit retains provenance",()=>{var r=Round();r.Events=[Damage("hit",10,"mate",40),Kill("k",20)];var c=Credit(Score(r),"k");Near(.09,c.PlayerCredits["mate"]);Near(.21,c.PlayerCredits["p"]);Yes(c.EvidenceIds.Contains("hit"),"lost damage evidence");});
        Test("flash credit cannot use outsider",()=>{var r=Round();var k=Kill("k",20);k.AssisterId="mate";k.FlashAssist=true;r.Events=[k];Near(.03,Credit(Score(r),"k").PlayerCredits["mate"]);k.AssisterId="outsider";Yes(!Credit(Score(r),"k").PlayerCredits.ContainsKey("outsider"),"outsider credit");});
        Test("economic duel weights differ",()=>{var r=Round();r.Events=[Kill("k",20)];r.EconomySnapshots.Single(s=>s.PlayerId=="p").EquipmentValue=6000;r.EconomySnapshots.Single(s=>s.PlayerId=="e").EquipmentValue=500;Yes(Score(r).FeatureValues![0]<1,"eco frag unweighted");r.EconomySnapshots.Single(s=>s.PlayerId=="p").EquipmentValue=500;r.EconomySnapshots.Single(s=>s.PlayerId=="e").EquipmentValue=6000;Yes(Score(r).FeatureValues![0]>1,"underdog frag unweighted");});
        Test("unknown event equipment stays unknown",()=>{var r=Round();var k=Kill("k",20);k.ActorState=null;r.Events=[k];var a=Score(r);Yes(a.Overall is null&&a.UnavailableReasons.Any(s=>s.Contains("装备")),"invented equipment");});
        Test("event state identity side tick time",()=>{foreach(var mutate in new Action<PlayerState>[] {s=>s.PlayerId="mate",s=>s.Side="CT",s=>s.Tick++,s=>s.Time+=1}){var r=Round();var k=Kill("k",20);mutate(k.ActorState!);r.Events=[k];Yes(Score(r).Overall is null,"invalid event state accepted");}});
        Test("strict no-kit ten second boundary",()=>{foreach(var time in new[]{40d,40.001}){var r=Round();r.Events=[Bomb("bomb_planted","plant",10),Kill("k",time)];Yes(Credit(Score(r),"k").Eligible==(time==40),"ten-second boundary");}});
        Test("strict kit five second boundary",()=>{foreach(var time in new[]{45d,45.001}){var r=Round();r.EconomySnapshots.Single(s=>s.PlayerId=="e2").DefuseKit=true;r.Events=[Bomb("bomb_planted","plant",10),Kill("k",time)];Yes(Credit(Score(r),"k").Eligible==(time==45),"five-second boundary");}});
        Test("defuser exception and abort",()=>{var r=Round();r.Events=[Bomb("bomb_planted","plant",10),Bomb("bomb_defuse_start","start",43,"e2"),Kill("k",46)];Yes(Credit(Score(r),"k").Eligible,"defuser excluded");r.Events.Insert(2,Bomb("bomb_defuse_aborted","abort",44,"e2"));Yes(!Credit(Score(r),"k").Eligible,"abort ignored");});
        Test("unknown bomb timer and kit degrade",()=>{foreach(var kit in new[]{true,false}){var r=Round();if(kit)r.EconomySnapshots.Single(s=>s.PlayerId=="e2").DefuseKit=null;else r.BombTimerSeconds=null;r.Events=[Bomb("bomb_planted","plant",10),Kill("k",46)];var a=Score(r);Yes(a.RoundSwing is null&&a.UnavailableReasons.Count>0,"invented bomb facts");}});
        Test("postplant residual excludes preplant kill",()=>{var r=Round();r.Events=[Kill("before",5),Bomb("bomb_planted","plant",10)];var a=Score(r);Yes(!a.Credits.Any(c=>c.EventId=="round-1-residual"&&c.PlayerCredits.GetValueOrDefault("p")>0),"preplant kill got residual");});
        Test("cleanup duplicate substitute invalid-round exclusion",()=>{var r=Round();r.Events=[Kill("k",20),Kill("duplicate",21),Kill("cleanup",101,"p","e2")];var absent=Round(2);absent.Participants.RemoveAll(p=>p.PlayerId=="p");absent.EconomySnapshots.RemoveAll(p=>p.PlayerId=="p");absent.Events=[Kill("outsider",20)];var invalid=Round(3);invalid.IsValid=false;invalid.Events=[Kill("invalid",20)];var a=new RatingEngine().Score(Match(r,absent,invalid),"p",Model());Near(1,a.PlayedRounds);Yes(!a.Credits.Any(c=>c.EventId is "duplicate" or "cleanup" or "outsider" or "invalid"),"excluded credit");});
        Test("recorded raw statistics settlement cannot extend Rating or Swing contribution",()=>{
            var r=Round();r.Events=[Kill("competitive",20)];var before=Score(r);
            r.StatisticsEndedAt=110;var exitDamage=Damage("exit-damage",101,"p",60);exitDamage.TargetId="e2";exitDamage.TargetState=State("e2","CT",exitDamage.Tick,exitDamage.Time,40);exitDamage.TargetHealthAfter=40;
            r.Events.Add(exitDamage);r.Events.Add(Kill("exit-kill",102,"p","e2"));var after=Score(r);
            Near(1,before.Raw.Kills);Near(2,after.Raw.Kills);Near(60,after.Raw.Damage);
            Near(before.Overall!.Value,after.Overall);Near(before.RoundSwing!.Value,after.RoundSwing);
            Yes(before.FeatureValues!.SequenceEqual(after.FeatureValues!),"exit combat changed Rating axes");
            Yes(!after.Credits.Any(c=>c.EventId.StartsWith("exit-",StringComparison.Ordinal)),"exit combat received scoring credit");
        });
        Test("same-clock post-outcome callbacks cannot enter Rating axes or Swing",()=>{
            var r=Round();r.Events=[Kill("competitive",20)];var before=Score(r);r.StatisticsEndedAt=105;
            var exit=Kill("same-clock-exit",100,"p","e2");var node=System.Text.Json.JsonSerializer.SerializeToNode(exit,DataJson.Options)!;node["afterRoundEnd"]=true;
            r.Events.Add(node.Deserialize<GameEvent>(DataJson.Options)!);var after=Score(r);
            Near(2,after.Raw.Kills);Near(before.Overall!.Value,after.Overall);Near(before.RoundSwing!.Value,after.RoundSwing);
            Yes(before.FeatureValues!.SequenceEqual(after.FeatureValues!),"same-clock exit changed axes");Yes(!after.Credits.Any(c=>c.EventId==exit.Id),"same-clock exit received credit");
        });
        Test("Rating damage uses event post-health instead of stale entity health",()=>{
            var r=Round();GameEvent Observed(GameEvent e,int hp){var node=System.Text.Json.JsonSerializer.SerializeToNode(e,DataJson.Options)!;node["targetHealthAfter"]=hp;return node.Deserialize<GameEvent>(DataJson.Options)!;}
            var first=Observed(Damage("first",10,"p",41),58);var fatal=Observed(Damage("fatal",10,"p",59),0);fatal.TargetState!.Health=100;
            r.Events=[first,fatal,Kill("kill-callback",10)];var s=Score(r);Near(99,s.Raw.Damage);Near(99,s.FeatureValues![1]);Yes(s.Overall is not null,"recorded fatal HP should not cause unavailability");
        });
        Test("unknown starting health leaves RS null",()=>{var r=Round();r.EconomySnapshots.Single(s=>s.PlayerId=="e2").Health=null;r.Events=[Kill("k",20)];Yes(Score(r).RoundSwing is null,"invented alive count");});
        Test("facts must match source SHA",()=>{var r=Round();r.Events=[Kill("k",20)];var facts=new RatingMatchFacts{SourceSha256=new string('d',64)};Yes(new RatingEngine().Score(Match(r),"p",Model(),facts).Overall is null,"source identity bypass");});
        Test("five second trade shares credit with the traded teammate",()=>{foreach(var gap in new[]{5d,5.001}){var r=Round();r.Events=[Kill("death",10,"e","mate"),Kill("revenge",10+gap)];r.Survivors=["p","e2"];var model=Model();model.ProbabilityCells.Add(Cell(2,1,false,80));model.ProbabilityCells.Add(Cell(1,1,false,50));model=RatingModelCodec.Seal(model);var c=Credit(Score(r,model:model),"revenge");Near(gap==5?.03:0,c.PlayerCredits.GetValueOrDefault("mate"));Yes(gap==5?c.EvidenceIds.Contains("death"):!c.EvidenceIds.Contains("death"),"trade provenance boundary");}});
        Test("reliable kit acquisition changes cutoff after defuse abort",()=>{var r=Round();var start=Bomb("bomb_defuse_start","start",40,"e2");start.ActorState!.DefuseKit=true;var abort=Bomb("bomb_defuse_aborted","abort",41,"e2");abort.ActorState!.DefuseKit=true;r.Events=[Bomb("bomb_planted","plant",10),start,abort,Kill("k",44)];Yes(Credit(Score(r),"k").Eligible,"fresh reliable kit ignored");});
        Test("unknown starting state does not turn known forty-damage KAST into zero",()=>{var r=Round();r.EconomySnapshots.Single(s=>s.PlayerId=="e2").Health=null;r.Survivors=["p","e2"];r.Events=[Damage("hit",10,"mate",40),Kill("k",20)];var a=Score(r,"mate");Near(100,a.ScoringKastPercent);Yes(a.Overall is null,"missing start invented");});
        Test("plant with no clock stays unknown even without a later kill",()=>{var r=Round();r.BombTimerSeconds=null;r.Events=[Bomb("bomb_planted","plant",10)];Yes(Score(r).RoundSwing is null,"missing plant clock invented");});
        Test("invalid source SHA and null facts cannot bypass identity",()=>{var r=Round();r.Events=[Kill("k",20)];var match=Match(r);match.SourceSha256="unknown";Yes(new RatingEngine().Score(match,"p",Model()).Overall is null,"invalid source accepted");var facts=new RatingMatchFacts{SourceSha256=new string('a',64),Frames=null!};Yes(new RatingEngine().Score(Match(r),"p",Model(),facts).Overall is null,"null facts accepted");});
        Test("future plant cannot select an earlier probability table",()=>{var model=Model();model.MinimumMapObservations=1;for(var ct=0;ct<=2;ct++)for(var t=0;t<=2;t++){var c=Cell(ct,t,false,ct==2?80:10);c.Map="de_mirage";model.ProbabilityCells.Add(c);}model=RatingModelCodec.Seal(model);var plain=Round();plain.Events=[Kill("early",5)];var planted=Round();planted.Events=[Kill("early",5),Bomb("bomb_planted","later",10)];var a=Score(plain,model:model);var b=Score(planted,model:model);Near(Credit(a,"early").PlayerCredits["p"],Credit(b,"early").PlayerCredits["p"]);Yes(a.Warnings.First()==b.Warnings.First(),"future plant changed initial map/global policy");});
        Test("fatal damage clears ongoing defuse before the kill callback",()=>{var r=Round();var fatal=Damage("fatal",45.5,"p",100);fatal.TargetId="e2";fatal.TargetState=State("e2","CT",4550,45.5,0);r.Events=[Bomb("bomb_planted","plant",10),Bomb("bomb_defuse_start","start",43,"e2"),fatal,Kill("other",46),Kill("callback",46.1,"p","e2")];Yes(!Credit(Score(r),"other").Eligible,"dead defuser retained the exception");});
        Test("recorded bomb terminal preserves residual and freezes cleanup",()=>{foreach(var terminal in new[]{"bomb_exploded","bomb_defused"}){var r=Round();var actor=terminal=="bomb_defused"?"e":"p";var target=terminal=="bomb_defused"?"p":"e";if(terminal=="bomb_defused"){r.Winner="CT";r.Survivors=["e","e2","mate"];}r.Events=[Bomb("bomb_planted","plant",10),Kill("post",20,actor,target)];var model=Model();model.ProbabilityCells.Add(Cell(2,1,true,60));model=RatingModelCodec.Seal(model);var before=Score(r,actor,model);r.Events.Add(Bomb(terminal,"end",50,actor));var ended=Score(r,actor,model);Near(Credit(before,"round-1-residual").PlayerCredits[actor],Credit(ended,"round-1-residual").PlayerCredits[actor]);r.Events.Add(Kill("cleanup",51,actor,terminal=="bomb_defused"?"mate":"e2"));var cleanup=Score(r,actor,model);Near(ended.RoundSwing!.Value,cleanup.RoundSwing);Near(ended.FeatureValues![0],cleanup.FeatureValues![0]);Yes(!cleanup.Credits.Any(c=>c.EventId=="cleanup"),"terminal cleanup earned scoring credit");}});
        Test("non-enemy damage consumes HP before enemy damage and forty-assist",()=>{foreach(var actor in new string?[]{"e2",null}){var r=Round();r.Survivors=["p","e2"];var prior=Damage("prior",5,"e2",70);prior.ActorId=actor;prior.ActorState=actor is null?null:State(actor,"CT",500,5);prior.TargetState!.Health=30;var hit=Damage("hit",10,"mate",50);hit.TargetState!.Health=0;r.Events=[prior,hit,Kill("kill",20,"mate")];var a=Score(r,"mate");Near(30,a.FeatureValues![1]);Yes(!Credit(a,"kill").EvidenceIds.Contains("prior"),"team/environment damage received enemy attribution");hit.Damage=29;hit.TargetState.Health=1;var finish=Damage("finish",19.99,"p",1);finish.TargetState!.Health=0;r.Events=[prior,hit,finish,Kill("kill",20)];a=Score(r,"mate");Near(29,a.FeatureValues![1]);Near(0,a.ScoringKastPercent);}});
        Test("freeze proxy ignores death callback equipment changes",()=>{var r=Round();var k=Kill("kill",20);r.Events=[k];var a=Score(r);k.TargetState!.EquipmentValue=0;k.ActorState!.EquipmentValue=100000;var b=Score(r);Near(a.FeatureValues![0],b.FeatureValues![0]);k.TargetState.EquipmentValue=null;Near(a.FeatureValues[0],Score(r).FeatureValues![0]);});
        Test("explicit event side mismatch cannot bypass participant identity",()=>{foreach(var actor in new[]{true,false}){var r=Round();var k=Kill("kill",20);if(actor)k.ActorSide="CT";else k.TargetSide="T";r.Events=[k];var a=Score(r);Yes(a.Overall is null&&!a.Credits.Any(c=>c.EventId=="kill"),"event side disagreed with participation");}});
        Test("supplementary facts cannot revive a known dead player",()=>{var r=Round();r.Events=[Kill("kill",20)];RatingStateFrame F(string id,int tick,double time,bool enemyAlive)=>new(){Round=1,EventId=id,Tick=tick,Time=time,Players=r.Participants.Select(p=>new RatingPlayerState{PlayerId=p.PlayerId,Side=p.Side,Alive=p.PlayerId!="e"||enemyAlive,DefuseKit=false}).ToList()};var facts=new RatingMatchFacts{SourceSha256=new string('a',64),Frames=[F("kill",2000,20,true)]};r.EconomySnapshots.Single(p=>p.PlayerId=="e").Health=0;var a=new RatingEngine().Score(Match(r),"p",Model(),facts);Yes(a.Overall is null&&!a.Credits.Any(c=>c.EventId=="kill"),"freeze dead player revived");r.EconomySnapshots.Single(p=>p.PlayerId=="e").Health=100;r.Events.Insert(0,new(){Id="observe",Kind="shot",Time=10,Tick=1000,ActorId="p"});facts.Frames.Insert(0,F("observe",1000,10,false));Yes(new RatingEngine().Score(Match(r),"p",Model(),facts).Overall is null,"later frame revived observed death");});
        Test("fatal damage retains the matching kill probability attribution",()=>{var r=Round();r.Events=[Damage("fatal",19.99,"p",100),Kill("kill",20)];var a=Score(r);Near(.3,Credit(a,"kill").PlayerCredits["p"]);Yes(Credit(a,"kill").EvidenceIds.Contains("fatal"),"fatal source evidence lost");});
        Test("known zero HP cannot begin a new defuse",()=>{var r=Round();var d=Damage("fatal",44,"p",100);d.TargetId="e2";d.TargetState=State("e2","CT",4400,44,0);r.Events=[Bomb("bomb_planted","plant",10),d,Bomb("bomb_defuse_start","dead-start",45,"e2"),Kill("other",46),Kill("callback",46.1,"p","e2")];Yes(!Credit(Score(r),"other").Eligible,"dead player restarted defuse exception");});
        Test("the fatal defuser kill retains its pre-death exception only",()=>{var r=Round();var d=Damage("fatal",45.5,"p",100);d.TargetId="e2";d.TargetState=State("e2","CT",4550,45.5,0);r.Events=[Bomb("bomb_planted","plant",10),Bomb("bomb_defuse_start","start",43,"e2"),d,Kill("other",46),Kill("callback",46.1,"p","e2")];var a=Score(r);Yes(Credit(a,"callback").Eligible&&!Credit(a,"other").Eligible,"fatal defuser exception was lost or propagated to another kill");});
        Test("reversed fatal callbacks cannot roll back residual settlement",()=>{foreach(var reversed in new[]{true,false})foreach(var sameClock in new[]{true,false}){var r=Round();var time=sameClock?10:10.1;var d=Damage("fatal-e2",time,"p",100);d.TargetId="e2";d.TargetState=State("e2","CT",d.Tick,time,0);r.Events=[Damage("fatal-e",10,"p",100),d,Kill("callback-first",10.2,"p",reversed?"e2":"e"),Kill("callback-second",10.3,"p",reversed?"e":"e2")];var a=Score(r);Near(.5,a.Credits.Where(c=>c.Kind=="kill").Sum(c=>c.PlayerCredits.GetValueOrDefault("p")));Near(0,Credit(a,"round-1-residual").PlayerCredits["p"]);}});
        Test("finite model parameters cannot yield a non-finite valid score",()=>{var r=Round();r.Events=[Kill("kill",20)];var model=Model();model.AxisScales=Enumerable.Repeat(double.Epsilon,6).ToArray();model=RatingModelCodec.Seal(model);var a=Score(r,model:model);Yes(a.Overall is null&&a.RoundSwing is null&&a.UnavailableReasons.Any(s=>s.Contains("数值")),"infinite score escaped as valid");});
        Test("strongest mode requires precise freeze and pre-event inventory facts",()=>{var r=Round();r.Events=[Kill("kill",20)];var model=Model();model.FeatureVersion="strongest-weapon-armor-v1";model=RatingModelCodec.Seal(model);Yes(Score(r,model:model).Overall is null,"invented strongest prices");RatingStateFrame Frame(string id,int tick,double time)=>new(){Round=1,EventId=id,Tick=tick,Time=time,Players=r.Participants.Select(p=>new RatingPlayerState{PlayerId=p.PlayerId,Side=p.Side,Alive=true,StrongestWeaponPrice=p.PlayerId=="p"?6000:p.PlayerId=="e"?500:3000,ArmorPrice=0,DefuseKit=false}).ToList()};var facts=new RatingMatchFacts{SourceSha256=new string('a',64),Frames=[Frame("round-1-freeze",0,0),Frame("kill",2000,20)]};var engine=new RatingEngine();var a=engine.Score(Match(r),"p",model,facts);Yes(a.Overall is not null&&a.FeatureValues![0]<1,"pre-event inventory facts unused");facts.Frames.RemoveAt(0);Yes(engine.Score(Match(r),"p",model,facts).Overall is null,"missing freeze strongest prices guessed");facts.Frames.Insert(0,Frame("round-1-freeze",0,0));facts.Frames[1].Players.Single(p=>p.PlayerId=="e").ArmorPrice=null;Yes(engine.Score(Match(r),"p",model,facts).Overall is null,"unknown pre-event armor guessed");});
        Console.WriteLine($"Rating rules: {count-failures.Count}/{count} passed");if(failures.Count>0)Environment.ExitCode=1;
    }
}
